# Generated by noon shell init. Source manually; no startup files are modified.
_noon_saved_status=$?
_noon_install() {
    local saved=$1 item
    _noon_complete() {
        local line path_mode current
        COMPREPLY=()
        path_mode=
        while IFS= read -r line; do
            case $line in
                __NOON_COMPLETE_PATH_FILE__) path_mode=file ;;
                __NOON_COMPLETE_PATH_DIR__) path_mode=dir ;;
                *) [[ -n $line ]] && COMPREPLY+=("$line") ;;
            esac
        done < <(NOON_COMPLETION_SHELL=bash command noon "${COMP_WORDS[@]:1:COMP_CWORD}" --generate-shell-completion 2>/dev/null)
        if [[ -n $path_mode ]]; then
            current=${COMP_WORDS[COMP_CWORD]-}
            [[ $current == = ]] && current=
            [[ $current == -*=* ]] && current=${current#*=}
            if [[ $path_mode == dir ]]; then
                while IFS= read -r line; do COMPREPLY+=("$line"); done < <(compgen -d -- "$current")
            else
                while IFS= read -r line; do COMPREPLY+=("$line"); done < <(compgen -f -- "$current")
            fi
        fi
        return 0
    }
    complete -o filenames -F _noon_complete noon

    # Bash before 5.1 executes only the first PROMPT_COMMAND array element.
    # Preserve scalar scripts verbatim there; newer Bash keeps array entries.
    local -a hooks=()
    local arrays=0
    if (( BASH_VERSINFO[0] > 5 || (BASH_VERSINFO[0] == 5 && BASH_VERSINFO[1] >= 1) )); then
        arrays=1
        if [[ $(declare -p PROMPT_COMMAND 2>/dev/null) == 'declare -a '* ]]; then
            for item in "${PROMPT_COMMAND[@]}"; do
                [[ $item == _noon_prompt ]] || hooks+=("$item")
            done
        elif [[ -n ${PROMPT_COMMAND-} && ${PROMPT_COMMAND-} != _noon_prompt ]]; then
            hooks+=("$PROMPT_COMMAND")
        fi
        PROMPT_COMMAND=("${hooks[@]}")
    else
        item=${PROMPT_COMMAND-}
        PROMPT_COMMAND=${item#$'_noon_prompt\n'}
    fi
    _noon_job='@JOB@'
    if [[ -n $_noon_job ]]; then
        _noon_directory=$PWD
        _noon_project=$(command noon shell entry --record -- bash "$_noon_job" '' "$PWD" "$PWD")
        _noon_prompt() {
            local saved=$?
            if [[ $PWD != "$_noon_directory" ]]; then
                _noon_project=$(command noon shell entry -- bash "$_noon_job" "$_noon_project" "$_noon_directory" "$PWD")
                _noon_directory=$PWD
            fi
            return "$saved"
        }
        if (( arrays )); then
            PROMPT_COMMAND=(_noon_prompt "${hooks[@]}")
        else
            PROMPT_COMMAND=$'_noon_prompt\n'"${PROMPT_COMMAND-}"
        fi
    fi
    return "$saved"
}
_noon_install "$_noon_saved_status"
